<div id="cancelDialog" class="fixed inset-0 z-[100] hidden items-center justify-center bg-slate-950/50 p-4"><div class="w-full max-w-md rounded-2xl bg-white p-5 shadow-xl"><div class="flex items-start justify-between"><div><h2 class="text-base font-extrabold text-slate-900">Batalkan Reservasi</h2><p class="mt-1 text-xs text-slate-500">Reservasi tetap tersimpan sebagai histori.</p></div><button type="button" onclick="closeCancel()" class="text-slate-400"><i class="fa-solid fa-xmark"></i></button></div><form id="cancelForm" method="POST" class="mt-4 space-y-3">@csrf<label class="block text-xs font-semibold text-slate-700">Alasan pembatalan<textarea name="alasan_pembatalan" required minlength="5" maxlength="1000" rows="4" class="mt-1 w-full rounded-xl border border-slate-200 p-3 text-sm outline-none focus:border-rose-400" placeholder="Tuliskan alasan pembatalan"></textarea></label><div class="flex justify-end gap-2"><button type="button" onclick="closeCancel()" class="rounded-lg border border-slate-200 px-4 py-2 text-xs font-semibold">Kembali</button><button class="rounded-lg bg-rose-600 px-4 py-2 text-xs font-bold text-white">Batalkan Reservasi</button></div></form></div></div>
<script>
function openCancel(id){const d=document.getElementById('cancelDialog');document.getElementById('cancelForm').action='{{ url('/admin/antrean') }}/'+id+'/batal';d.classList.remove('hidden');d.classList.add('flex')}
function closeCancel(){const d=document.getElementById('cancelDialog');d.classList.add('hidden');d.classList.remove('flex')}
(() => {
    const form = document.getElementById('queueFilters');
    if (!form) return;
    form.querySelectorAll('select, input[type="date"]').forEach(input => input.addEventListener('change', () => form.requestSubmit()));
    form.querySelector('input[name="q"]')?.addEventListener('change', () => form.requestSubmit());
})();
</script>
